int sortMergeJoin(Buffer *buf)
{
	int i = 0;
	size_t rIndex = 0;
	size_t sIndex = 0;
	std::vector<Relation> rTuples;
	std::vector<Relation> sTuples;
	Relation rTuples[TUPLE_PER_BLK];
	Relation sTuples[TUPLE_PER_BLK];
	unsigned char *blk = NULL;

	if (buf == NULL)
	{
		return -1;
	}

	if (mergeSort(buf, SORT_R) != 0 || mergeSort(buf, SORT_S) != 0)
	{
		return -1;
	}

	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, true);
	for (i = 0; i < R_BLK_NUM; i++)
	{
		blk = readBlockFromDisk(MERGE_R_RET_ADDR + i, buf);
		if (blk == NULL)
		{
			return -1;
		}

		readTuplesFromBlock(blk, rTuples);
		rTuples.insert(rTuples.end(), rTuples, rTuples + TUPLE_PER_BLK);
		freeBlockInBuffer(blk, buf);
	}

	for (i = 0; i < S_BLK_NUM; i++)
	{
		blk = readBlockFromDisk(MERGE_S_RET_ADDR + i, buf);
		if (blk == NULL)
		{
			return -1;
		}

		readTuplesFromBlock(blk, sTuples);
		sTuples.insert(sTuples.end(), sTuples, sTuples + TUPLE_PER_BLK);
		freeBlockInBuffer(blk, buf);
	}

	while (rIndex < rTuples.size() && sIndex < sTuples.size())
	{
		if (rTuples[rIndex].attr1 < sTuples[sIndex].attr1)
		{
			rIndex++;
			continue;
		}
		if (rTuples[rIndex].attr1 > sTuples[sIndex].attr1)
		{
			sIndex++;
			continue;
		}

		int joinKey = rTuples[rIndex].attr1;
		size_t rStart = rIndex;
		size_t sStart = sIndex;

		while (rIndex < rTuples.size() && rTuples[rIndex].attr1 == joinKey)
		{
			rIndex++;
		}
		while (sIndex < sTuples.size() && sTuples[sIndex].attr1 == joinKey)
		{
			sIndex++;
		}

		for (size_t rPos = rStart; rPos < rIndex; rPos++)
		{
			for (size_t sPos = sStart; sPos < sIndex; sPos++)
			{
				output(buf, SMJ_RET_ADDR, rTuples[rPos].attr1, rTuples[rPos].attr2, sTuples[sPos].attr2);
			}
		}
	}

	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, false, true);
	cout << "IOs: " << buf->numIO << endl;
	return 0;
}

