void setNextAddr(unsigned char *blk, unsigned int nextAddr)
{
	memcpy(blk + BLK_SIZE - PTR_SIZE, &nextAddr, PTR_SIZE);
}

void setHashTupleCount(unsigned char *blk, int count)
{
