}

void resetHashWriter(unsigned int addr)
{
	int i = 0;

	for (i = 0; i < BUCKET_NUM; i++)
	{
		gHashBlocks[i] = NULL;
		gHashCounts[i] = 0;
		gHashAddrs[i] = addr + i * HASH_BUCKET_STRIDE;
	}
}
}

void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		gWriteBlock = NULL;
		gWriteOffset = 0;
		gWriteAddr = addr;
	}

	if (buf == NULL)
	{
		return;
	}

	if (source != NULL && size > 0)
	{
		if (size > buf->blkSize - PTR_SIZE)
		{
			return;
		}

		if (gWriteBlock == NULL)
		{
			gWriteBlock = getNewBlockInBuffer(buf);
			if (gWriteBlock == NULL)
			{
				return;
			}
			gWriteOffset = 0;
			gWriteAddr = addr;
		}

		if (gWriteOffset + size > buf->blkSize - PTR_SIZE)
		{
			setNextAddr(gWriteBlock, gWriteAddr + 1);
			if (writeBlockToDisk(gWriteBlock, gWriteAddr, buf) != 0)
			{
				gWriteBlock = NULL;
				gWriteOffset = 0;
				return;
			}
			gWriteAddr++;
			gWriteBlock = getNewBlockInBuffer(buf);
			if (gWriteBlock == NULL)
			{
				gWriteOffset = 0;
				return;
			}
			gWriteOffset = 0;
		}

		memcpy(gWriteBlock + gWriteOffset, source, size);
		gWriteOffset += size;
	}

	if (push && gWriteBlock != NULL)
	{
		setNextAddr(gWriteBlock, 0);
		if (writeBlockToDisk(gWriteBlock, gWriteAddr, buf) == 0)
		{
			gWriteAddr++;
		}
		gWriteBlock = NULL;
		gWriteOffset = 0;
	}
}

void readTuplesFromBlock(unsigned char *blk, Relation *R)
{
	int i = 0;

	if (blk == NULL || R == NULL)
	{
		return;
	}

	for (i = 0; i < TUPLE_PER_BLK; i++)
	{
		memcpy(&R[i], blk + i * sizeof(Relation), sizeof(Relation));
	}
}

void output(Buffer *buf, unsigned int addr, int attr1, int attr2, int attr3)
{
	Relation3 tuple = { attr1, attr2, attr3 };

	std::cout << attr1 << " " << attr2 << " " << attr3 << std::endl;
	pushToWrite(buf, reinterpret_cast<unsigned char *>(&tuple), sizeof(tuple), addr);
}

void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
{
	int bucket = 0;

	if (reset)
	{
		resetHashWriter(addr);
	}

	if (buf == NULL)
	{
		return;
	}

	if (R != NULL)
	{
		bucket = R->attr1 % BUCKET_NUM;
		if (bucket < 0)
		{
			bucket += BUCKET_NUM;
		}

		if (gHashBlocks[bucket] == NULL)
		{
			gHashBlocks[bucket] = getNewBlockInBuffer(buf);
			if (gHashBlocks[bucket] == NULL)
			{
				return;
			}
			gHashCounts[bucket] = 0;
		}

		if (gHashCounts[bucket] >= HASH_PER_BLK)
		{
			setHashTupleCount(gHashBlocks[bucket], gHashCounts[bucket]);
			setNextAddr(gHashBlocks[bucket], gHashAddrs[bucket] + 1);
			if (writeBlockToDisk(gHashBlocks[bucket], gHashAddrs[bucket], buf) != 0)
			{
				gHashBlocks[bucket] = NULL;
				gHashCounts[bucket] = 0;
				return;
			}
			gHashAddrs[bucket]++;
			gHashBlocks[bucket] = getNewBlockInBuffer(buf);
			if (gHashBlocks[bucket] == NULL)
			{
				gHashCounts[bucket] = 0;
				return;
			}
			gHashCounts[bucket] = 0;
		}

		memcpy(gHashBlocks[bucket] + gHashCounts[bucket] * sizeof(Relation), R, sizeof(Relation));
		gHashCounts[bucket]++;
	}

	if (push)
	{
		for (bucket = 0; bucket < BUCKET_NUM; bucket++)
		{
			if (gHashBlocks[bucket] != NULL)
			{
				setHashTupleCount(gHashBlocks[bucket], gHashCounts[bucket]);
				setNextAddr(gHashBlocks[bucket], 0);
				writeBlockToDisk(gHashBlocks[bucket], gHashAddrs[bucket], buf);
				gHashBlocks[bucket] = NULL;
				gHashCounts[bucket] = 0;
				gHashAddrs[bucket]++;
			}
		}
	}
}

int readHashFromBlock(unsigned char *blk, Relation *R)
{
	int count = 0;
	int i = 0;

	if (blk == NULL || R == NULL)
	{
		return 0;
	}

	memcpy(&count, blk + HASH_PER_BLK * sizeof(Relation), sizeof(count));
	if (count < 0)
	{
		count = 0;
	}
	if (count > HASH_PER_BLK)
	{
		count = HASH_PER_BLK;
	}

	for (i = 0; i < count; i++)
	{
		memcpy(&R[i], blk + i * sizeof(Relation), sizeof(Relation));
	}

	return count;
}

