using namespace std;

int hashJoin(Buffer *buf)
{
	int i = 0;
	int j = 0;
	int bucket = 0;
	int tupleCount = 0;
	unsigned char *blk = NULL;
	Relation tuples[TUPLE_PER_BLK];
	Relation hashTuples[HASH_PER_BLK];
	int rBucketTuples[BUCKET_NUM] = { 0 };
	int sBucketTuples[BUCKET_NUM] = { 0 };

	if (buf == NULL)
	{
		return -1;
	}

	pushToWrite(buf, NULL, 0, HJ_RET_ADDR, true);
	pushHashToWrite(buf, NULL, HASH_R_ADDR, true);
	for (i = 0; i < R_BLK_NUM; i++)
	{
		blk = readBlockFromDisk(R_ADDR + i, buf);
		if (blk == NULL)
		{
			return -1;
		}

		readTuplesFromBlock(blk, tuples);
		for (j = 0; j < TUPLE_PER_BLK; j++)
		{
			bucket = tuples[j].attr1 % BUCKET_NUM;
			if (bucket < 0)
			{
				bucket += BUCKET_NUM;
			}
			rBucketTuples[bucket]++;
			pushHashToWrite(buf, &tuples[j], HASH_R_ADDR);
		}

		freeBlockInBuffer(blk, buf);
	}
	pushHashToWrite(buf, NULL, HASH_R_ADDR, false, true);

	pushHashToWrite(buf, NULL, HASH_S_ADDR, true);
	for (i = 0; i < S_BLK_NUM; i++)
	{
		blk = readBlockFromDisk(S_ADDR + i, buf);
		if (blk == NULL)
		{
			return -1;
		}

		readTuplesFromBlock(blk, tuples);
		for (j = 0; j < TUPLE_PER_BLK; j++)
		{
			bucket = tuples[j].attr1 % BUCKET_NUM;
			if (bucket < 0)
			{
				bucket += BUCKET_NUM;
			}
			sBucketTuples[bucket]++;
			pushHashToWrite(buf, &tuples[j], HASH_S_ADDR);
		}

		freeBlockInBuffer(blk, buf);
	}
	pushHashToWrite(buf, NULL, HASH_S_ADDR, false, true);

	for (bucket = 0; bucket < BUCKET_NUM; bucket++)
	{
		int rBlockNum = (rBucketTuples[bucket] + HASH_PER_BLK - 1) / HASH_PER_BLK;
		int sBlockNum = (sBucketTuples[bucket] + HASH_PER_BLK - 1) / HASH_PER_BLK;
		std::unordered_multimap<int, Relation> hashTable;

		if (rBlockNum == 0 || sBlockNum == 0)
		{
			continue;
		}

		hashTable.reserve(static_cast<size_t>(rBucketTuples[bucket]));
		for (i = 0; i < rBlockNum; i++)
		{
			blk = readBlockFromDisk(HASH_R_ADDR + bucket * HASH_BUCKET_STRIDE + i, buf);
			if (blk == NULL)
			{
				return -1;
			}

			tupleCount = readHashFromBlock(blk, hashTuples);
			for (j = 0; j < tupleCount; j++)
			{
				hashTable.emplace(hashTuples[j].attr1, hashTuples[j]);
			}

			freeBlockInBuffer(blk, buf);
		}

		for (i = 0; i < sBlockNum; i++)
		{
			blk = readBlockFromDisk(HASH_S_ADDR + bucket * HASH_BUCKET_STRIDE + i, buf);
			if (blk == NULL)
			{
				return -1;
			}

			tupleCount = readHashFromBlock(blk, hashTuples);
			for (j = 0; j < tupleCount; j++)
			{
				auto matches = hashTable.equal_range(hashTuples[j].attr1);
				for (auto it = matches.first; it != matches.second; ++it)
				{
					output(buf, HJ_RET_ADDR, it->second.attr1, it->second.attr2, hashTuples[j].attr2);
				}
			}

			freeBlockInBuffer(blk, buf);
		}
	}

	pushToWrite(buf, NULL, 0, HJ_RET_ADDR, false, true);
	cout << "IOs: " << buf->numIO << endl;
	return 0;
}

